create table "public"."match_results" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone,
    "onboarding_profile_id" bigint not null
);

alter table "public"."match_results" enable row level security;

CREATE UNIQUE INDEX match_results_pkey ON public.match_results USING btree (id);

alter table "public"."match_results" add constraint "match_results_pkey" PRIMARY KEY using index "match_results_pkey";

alter table "public"."match_results" add constraint "match_results_onboarding_profile_id_fkey" FOREIGN KEY (onboarding_profile_id) REFERENCES onboarding_profiles(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;

alter table "public"."match_results" validate constraint "match_results_onboarding_profile_id_fkey";

create policy "Enable insert for users based on user id"
on "public"."match_results"
as permissive
for insert
to authenticated
with check ((EXISTS ( SELECT 1
   FROM onboarding_profiles op
  WHERE ((op.id = match_results.onboarding_profile_id) AND (op.user_id = ( SELECT auth.uid() AS uid))))));


create policy "Enable users to view their own data only"
on "public"."match_results"
as permissive
for select
to authenticated
using ((EXISTS ( SELECT 1
   FROM onboarding_profiles op
  WHERE ((op.id = match_results.onboarding_profile_id) AND (op.user_id = ( SELECT auth.uid() AS uid))))));